package com.timetune;
import com.timetune.domain.*;import com.timetune.service.GameEngineService;import com.timetune.controller.SongController;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/games") public class GameController {private final GameEngineService engine;public GameController(GameEngineService e){engine=e;}public record CreateRequest(List<String> playerNames,GameSession.Mode mode){}public record PlayerDto(UUID id,String name,int tokens,List<SongController.SongDto> timeline){}public record GameDto(UUID id,GameSession.Mode mode,GameSession.Status status,int activePlayerIndex,List<PlayerDto> players){}public record PromptDto(UUID songId,String audioStatus){}public record PlaceRequest(UUID playerId,int insertionIndex){}@PostMapping public GameDto create(@RequestBody CreateRequest r){return map(engine.create(r.playerNames(),r.mode()==null?GameSession.Mode.LOCAL:r.mode()));}@PostMapping("/{id}/start")public GameDto start(@PathVariable UUID id){return map(engine.start(id));}@GetMapping("/{id}")public GameDto get(@PathVariable UUID id){return map(engine.require(id));}@GetMapping("/{id}/prompt")public PromptDto prompt(@PathVariable UUID id){return new PromptDto(engine.prompt(id).getId(),"MOCK_READY");}@PostMapping("/{id}/placement")public Map<String,Object> place(@PathVariable UUID id,@RequestBody PlaceRequest r){boolean correct=engine.place(id,r.playerId(),r.insertionIndex());return Map.of("correct",correct,"game",map(engine.require(id)));}@PostMapping("/{id}/reveal")public SongController.SongDto reveal(@PathVariable UUID id){return SongController.dto(engine.prompt(id));}private GameDto map(GameSession s){return new GameDto(s.getId(),s.getMode(),s.getStatus(),s.getActivePlayerIndex(),s.getPlayers().stream().map(p->new PlayerDto(p.getId(),p.getDisplayName(),p.getTokenBank().getBalance(),p.getTimeline().getOfficialCards().stream().map(SongController::dto).toList())).toList());}}